[DataContract]public enum BusbarKind{[EnumMember]Unknown,[EnumMember]BusbarAssembly,[EnumMember]BuswayAssembly}
[DataContract]public enum BoardCurrentEvidence{[EnumMember]Unknown,[EnumMember]FlowSinusoidal,[EnumMember]ExternalRms}
[DataContract]public sealed class BusbarRating {
[DataMember]public string Reference{get;set;}[DataMember]public BusbarKind Kind{get;set;}[DataMember]public string Configuration{get;set;}[DataMember]public bool? HasNeutral{get;set;}[DataMember]public double? RatedCurrentA{get;set;}[DataMember]public double? NeutralRatedA{get;set;}[DataMember]public double? OperatingVoltageMaxV{get;set;}[DataMember]public double? FrequencyHz{get;set;}[DataMember]public double? IcwKA{get;set;}[DataMember]public double? IcwSeconds{get;set;}[DataMember]public double? IpkKA{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string Conditions{get;set;}
public BusbarRating(){Reference=Configuration=Source=DataVersion=Conditions="";}public BusbarRating Copy(){return (BusbarRating)MemberwiseClone();}public void Validate(){if(!Enum.IsDefined(typeof(BusbarKind),Kind))throw new InvalidDataException("Tipo de conjunto desconhecido.");foreach(var v in new[]{RatedCurrentA,NeutralRatedA,OperatingVoltageMaxV,FrequencyHz,IcwKA,IcwSeconds,IpkKA})if(v.HasValue)Project.Range(v.Value,.000001,1e12,"dado nominal do conjunto");foreach(var s in new[]{Reference,Configuration,Source,DataVersion,Conditions})ReturnSizing.Text(s,false);}
}
[DataContract]public sealed class BusbarRequirements {
[DataMember,DisplayName("Origem das correntes de operação")]public BoardCurrentEvidence CurrentEvidence{get;set;}[DataMember,DisplayName("I RMS externo L1 (A)")]public double? L1RmsA{get;set;}[DataMember,DisplayName("I RMS externo L2 (A)")]public double? L2RmsA{get;set;}[DataMember,DisplayName("I RMS externo L3 (A)")]public double? L3RmsA{get;set;}[DataMember,DisplayName("I RMS externo N (A)")]public double? NeutralRmsA{get;set;}[DataMember,DisplayName("Neutro necessário no conjunto")]public bool? RequiresNeutral{get;set;}[DataMember,DisplayName("Fonte/modelo/condições das correntes")]public string CurrentReference{get;set;}[DataMember,DisplayName("Prova do regime senoidal (se usar fluxo)")]public string SinusoidalReference{get;set;}[DataMember,DisplayName("Fator combinado de capacidade (0..1)")]public double? CapacityFactor{get;set;}[DataMember,DisplayName("Documento de correções (THD/temperatura/montagem)")]public string CorrectionReference{get;set;}[DataMember,DisplayName("Condições de uso / ambiente / THD")]public string OperatingConditions{get;set;}[DataMember,DisplayName("Montagem/suportes/acessórios conferidos")]public bool? MountingVerified{get;set;}[DataMember,DisplayName("Documento de montagem aplicável")]public string MountingReference{get;set;}[DataMember,DisplayName("Limite RMS prospectivo durante corte (kA)")]public double? RequiredRmsUpperKA{get;set;}[DataMember,DisplayName("Tempo total requerido (s)")]public double? RequiredSeconds{get;set;}[DataMember,DisplayName("Pico prospectivo requerido (kA)")]public double? RequiredPeakKA{get;set;}[DataMember,DisplayName("Evidência do envelope/pico/tempo total")]public string FaultReference{get;set;}[DataMember,DisplayName("Hipóteses dos limites de curto")]public string FaultConditions{get;set;}
public BusbarRequirements(){CurrentReference=SinusoidalReference=CorrectionReference=OperatingConditions=MountingReference=FaultReference=FaultConditions="";}public BusbarRequirements Copy(){return (BusbarRequirements)MemberwiseClone();}public void Validate(){if(!Enum.IsDefined(typeof(BoardCurrentEvidence),CurrentEvidence))throw new InvalidDataException("Origem das correntes desconhecida.");foreach(var v in new[]{L1RmsA,L2RmsA,L3RmsA,NeutralRmsA,RequiredRmsUpperKA,RequiredSeconds,RequiredPeakKA})if(v.HasValue)Project.Range(v.Value,0,1e12,"exigência do conjunto");if(CapacityFactor.HasValue)Project.Range(CapacityFactor.Value,.000001,1,"fator do conjunto");foreach(var s in new[]{CurrentReference,SinusoidalReference,CorrectionReference,OperatingConditions,MountingReference,FaultReference,FaultConditions})ReturnSizing.Text(s,false);}
}
[DataContract]public sealed class BusbarBinding {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,Browsable(false)]public string ElectricalContext{get;set;}[DataMember,Browsable(false)]public BusbarRating Rating{get;set;}[DataMember,Browsable(false)]public BusbarRequirements Requirements{get;set;}
public BusbarBinding(){Engine=BusbarSelection.EngineId;ElectricalContext="";Requirements=new BusbarRequirements();}public BusbarBinding Copy(){return new BusbarBinding{Engine=Engine,ElectricalContext=ElectricalContext,Rating=Rating==null?null:Rating.Copy(),Requirements=Requirements.Copy()};}public void Validate(){if(Engine!=BusbarSelection.EngineId||Requirements==null)throw new InvalidDataException("Revisão/requisitos do conjunto desconhecidos.");ReturnSizing.Text(ElectricalContext,false);Requirements.Validate();if(Rating!=null)Rating.Validate();}
}
public sealed class BusbarResult{public string Status,Detail;public bool Accepted,Failed;public double[] PhaseRmsA;public double? NeutralRmsA,CorrectedRatedA,CorrectedNeutralA;}
public static class BusbarSelection {
public const string EngineId="cs-conjuntos-barras-v1";public const string Header="Reference;Kind;Configuration;HasNeutral;RatedCurrentA;NeutralRatedA;OperatingVoltageMaxV;FrequencyHz;IcwKA;IcwSeconds;IpkKA;Source;DataVersion;Conditions";
sealed class Input:Exception{public Input(string s):base(s){}}static void Need(bool ok,string message){if(!ok)throw new Input(message);}static bool Trace(string s){return !String.IsNullOrWhiteSpace(s)&&!s.TrimStart().StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase);}static void AppendJson(StringBuilder s,object obj,Type type){if(obj==null)return;using(var m=new MemoryStream()){new DataContractJsonSerializer(type).WriteObject(m,obj);s.Append(Convert.ToBase64String(m.ToArray()));}}
public static string Context(Project p,Board b){if(!p.Boards.Contains(b)||b.Circuits.Count==0)throw new InvalidDataException("Selecione quadro com circuitos.");var s=new StringBuilder(FaultTimeTrace.Context(p,b.Circuits[0])+"|"+b.Id);AppendJson(s,p.FlowSettings,typeof(NetworkFlowSettings));foreach(var c in p.Boards.SelectMany(x=>x.Circuits))AppendJson(s,c.FlowLoad,typeof(NetworkFlowLoad));using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(s.ToString()))).Replace("-","").ToLowerInvariant();}
public static List<BusbarRating> ReferenceCatalog(){return new List<BusbarRating>{new BusbarRating{Reference="KTA800-3LPE-standard-50Hz",Kind=BusbarKind.BuswayAssembly,Configuration="KTA3L+PE-standard",HasNeutral=false,RatedCurrentA=800,OperatingVoltageMaxV=1000,FrequencyHz=50,IcwKA=31,IcwSeconds=1,IpkKA=64,Source="Schneider DEBU021EN04/2026 printedp144 PDFp146; https://download.se.com/files?p_Doc_Ref=DEBU021EN&p_enDocType=Catalog&p_File_Name=Canalis+KTA+Catalogue_DEBU021EN_04+2026.pdf",DataVersion="04/2026",Conditions="Factory3L+PE standard; indoor edgewise/flat/vertical per p168/installation guide;35C24h average/40Cmax; corrections/harmonics require applicable evidence; no neutral rating inferred"},new BusbarRating{Reference="KTA800-3LPE-standard-60Hz",Kind=BusbarKind.BuswayAssembly,Configuration="KTA3L+PE-standard",HasNeutral=false,RatedCurrentA=800,OperatingVoltageMaxV=1000,FrequencyHz=60,IcwKA=31,IcwSeconds=1,IpkKA=64,Source="Schneider DEBU021EN04/2026 printedp144 PDFp146; https://download.se.com/files?p_Doc_Ref=DEBU021EN&p_enDocType=Catalog&p_File_Name=Canalis+KTA+Catalogue_DEBU021EN_04+2026.pdf",DataVersion="04/2026",Conditions="Factory3L+PE standard; indoor edgewise/flat/vertical per p168/installation guide;35C24h average/40Cmax; corrections/harmonics require applicable evidence; no neutral rating inferred"},new BusbarRating{Reference="KTA1000-3LPE-standard-50Hz",Kind=BusbarKind.BuswayAssembly,Configuration="KTA3L+PE-standard",HasNeutral=false,RatedCurrentA=1000,OperatingVoltageMaxV=1000,FrequencyHz=50,IcwKA=50,IcwSeconds=1,IpkKA=110,Source="Schneider DEBU021EN04/2026 printedp144 PDFp146; https://download.se.com/files?p_Doc_Ref=DEBU021EN&p_enDocType=Catalog&p_File_Name=Canalis+KTA+Catalogue_DEBU021EN_04+2026.pdf",DataVersion="04/2026",Conditions="Factory3L+PE standard; indoor edgewise/flat/vertical per p168/installation guide;35C24h average/40Cmax; corrections/harmonics require applicable evidence; no neutral rating inferred"},new BusbarRating{Reference="KTA1000-3LPE-standard-60Hz",Kind=BusbarKind.BuswayAssembly,Configuration="KTA3L+PE-standard",HasNeutral=false,RatedCurrentA=1000,OperatingVoltageMaxV=1000,FrequencyHz=60,IcwKA=50,IcwSeconds=1,IpkKA=110,Source="Schneider DEBU021EN04/2026 printedp144 PDFp146; https://download.se.com/files?p_Doc_Ref=DEBU021EN&p_enDocType=Catalog&p_File_Name=Canalis+KTA+Catalogue_DEBU021EN_04+2026.pdf",DataVersion="04/2026",Conditions="Factory3L+PE standard; indoor edgewise/flat/vertical per p168/installation guide;35C24h average/40Cmax; corrections/harmonics require applicable evidence; no neutral rating inferred"},new BusbarRating{Reference="KTA1250-3LPE-standard-50Hz",Kind=BusbarKind.BuswayAssembly,Configuration="KTA3L+PE-standard",HasNeutral=false,RatedCurrentA=1250,OperatingVoltageMaxV=1000,FrequencyHz=50,IcwKA=50,IcwSeconds=1,IpkKA=110,Source="Schneider DEBU021EN04/2026 printedp144 PDFp146; https://download.se.com/files?p_Doc_Ref=DEBU021EN&p_enDocType=Catalog&p_File_Name=Canalis+KTA+Catalogue_DEBU021EN_04+2026.pdf",DataVersion="04/2026",Conditions="Factory3L+PE standard; indoor edgewise/flat/vertical per p168/installation guide;35C24h average/40Cmax; corrections/harmonics require applicable evidence; no neutral rating inferred"},new BusbarRating{Reference="KTA1250-3LPE-standard-60Hz",Kind=BusbarKind.BuswayAssembly,Configuration="KTA3L+PE-standard",HasNeutral=false,RatedCurrentA=1250,OperatingVoltageMaxV=1000,FrequencyHz=60,IcwKA=50,IcwSeconds=1,IpkKA=110,Source="Schneider DEBU021EN04/2026 printedp144 PDFp146; https://download.se.com/files?p_Doc_Ref=DEBU021EN&p_enDocType=Catalog&p_File_Name=Canalis+KTA+Catalogue_DEBU021EN_04+2026.pdf",DataVersion="04/2026",Conditions="Factory3L+PE standard; indoor edgewise/flat/vertical per p168/installation guide;35C24h average/40Cmax; corrections/harmonics require applicable evidence; no neutral rating inferred"}};}
public static List<BusbarRating> Import(string file){return ComponentCsv.Import<BusbarRating>(file,Header,r=>r.Validate(),r=>r.Reference+"|"+r.Configuration+"|"+r.FrequencyHz);}public static void Export(IEnumerable<BusbarRating> rows,string file){ComponentCsv.Export(rows,file,Header,r=>r.Validate(),r=>r.Reference+"|"+r.Configuration+"|"+r.FrequencyHz);}
public static BusbarBinding Bind(Project p,Board b,BusbarRating rating,BusbarRequirements requirements){var binding=new BusbarBinding{Rating=rating.Copy(),Requirements=requirements.Copy(),ElectricalContext=Context(p,b)};binding.Validate();return binding;}
public static void AppendReport(Project p,Study study,StringBuilder text,IEnumerable<string> selected){var ids=selected==null?null:new HashSet<string>(selected);foreach(var board in p.Boards){if(board.BusbarSelection==null||!study.Busbars.ContainsKey(board.Id)||(ids!=null&&!board.Circuits.Any(c=>ids.Contains(c.Id))))continue;var result=study.Busbars[board.Id];text.AppendLine("\r\nCONJUNTO DE BARRAS/BUSWAY — "+board.Id+" / "+EngineId);text.AppendLine(result.Status+". "+result.Detail);text.AppendLine("Correntes/requisitos do quadro completo; seleção do relatório restringe quadros mostrados, não recalcula uma fração do conjunto.");}}
public static BusbarRating Recommend(Project p,Board b,IEnumerable<BusbarRating> rows,BusbarRequirements requirements){var options=rows.ToList();if(options.Count>100000)throw new InvalidDataException("Catálogo excede100000 candidatos.");foreach(var option in options){if(option==null)throw new InvalidDataException("Candidato ausente.");option.Validate();}foreach(var option in options.OrderBy(x=>x.RatedCurrentA??Double.MaxValue).ThenBy(x=>x.IcwKA??Double.MaxValue))if(Evaluate(p,b,Bind(p,b,option,requirements)).Accepted)return option;return null;}
public static BusbarResult Evaluate(Project p,Board b,BusbarBinding binding){p.Validate();var result=new BusbarResult();if(binding==null){result.Status="Conjunto não selecionado";return result;}binding.Validate();try{Need(p.Boards.Contains(b)&&b.Circuits.Count>0,"Quadro sem circuito/fora do projeto.");Need(binding.ElectricalContext==Context(p,b),"Fonte/rede/fluxo alterados desde a seleção; revincule as exigências.");var r=binding.Rating;var q=binding.Requirements;Need(r!=null&&r.Kind!=BusbarKind.Unknown&&new[]{r.Reference,r.Configuration,r.Source,r.DataVersion,r.Conditions}.All(Trace),"Catálogo/configuração/rastreabilidade incompletos.");Need(r.RatedCurrentA.HasValue&&r.OperatingVoltageMaxV.HasValue&&r.FrequencyHz.HasValue&&r.HasNeutral.HasValue,"Dados nominais/polos incompletos.");Need(new[]{q.CurrentReference,q.CorrectionReference,q.OperatingConditions,q.MountingReference,q.FaultReference,q.FaultConditions}.All(Trace),"Declare evidências de corrente/correções/montagem/curto.");Need(q.RequiresNeutral.HasValue&&q.CapacityFactor.HasValue&&q.MountingVerified==true,"Neutro/correção/montagem não conferidos.");Need(q.RequiredRmsUpperKA.HasValue&&q.RequiredSeconds.HasValue&&q.RequiredSeconds>0&&q.RequiredPeakKA.HasValue&&q.RequiredRmsUpperKA>0&&q.RequiredPeakKA>0,"Envelope prospectivo, pico ou tempo total ausentes.");Need(r.IcwKA.HasValue&&r.IcwSeconds.HasValue&&r.IpkKA.HasValue,"Suportabilidade de catálogo incompleta.");double[] currents;double neutral;if(q.CurrentEvidence==BoardCurrentEvidence.ExternalRms){Need(q.L1RmsA.HasValue&&q.L2RmsA.HasValue&&q.L3RmsA.HasValue&&q.NeutralRmsA.HasValue,"Correntes RMS por fase/N desconhecidas.");currents=new[]{q.L1RmsA.Value,q.L2RmsA.Value,q.L3RmsA.Value};neutral=q.NeutralRmsA.Value;}else{Need(q.CurrentEvidence==BoardCurrentEvidence.FlowSinusoidal&&Trace(q.SinusoidalReference),"Fluxo fundamental exige prova de regime senoidal; senão informe RMS externo.");var flow=NetworkFlow.Run(p);Need(flow.Converged,"Fluxo não convergido: "+flow.Detail);var sum=new Complex[4];foreach(var c in b.Circuits){var row=flow.For(c);Need(row!=null,"Circuito ausente no fluxo.");for(int i=0;i<4;i++)sum[i]+=row.Current[i];}currents=sum.Take(3).Select(x=>x.Magnitude).ToArray();neutral=sum[3].Magnitude;}
result.PhaseRmsA=currents;result.NeutralRmsA=neutral;result.CorrectedRatedA=r.RatedCurrentA*q.CapacityFactor;result.CorrectedNeutralA=r.NeutralRatedA*q.CapacityFactor;var failures=new List<string>();if(q.CurrentEvidence==BoardCurrentEvidence.ExternalRms&&p.FlowSettings!=null){var known=NetworkFlow.Run(p);if(known.Converged){var fundamental=new Complex[4];foreach(var c in b.Circuits){var measured=known.For(c);Need(measured!=null,"Circuito ausente no fluxo existente.");for(int i=0;i<4;i++)fundamental[i]+=measured.Current[i];}if(Enumerable.Range(0,3).Any(i=>currents[i]+1e-7<fundamental[i].Magnitude)||neutral+1e-7<fundamental[3].Magnitude)failures.Add("RMS externo inferior à fundamental doF22 no mesmo caso");}}if(b.Voltage>r.OperatingVoltageMaxV||p.Frequency!=r.FrequencyHz)failures.Add("tensão/frequência incompatíveis");if(currents.Max()>result.CorrectedRatedA)failures.Add("maior fase acima da capacidade corrigida");bool physicalN=b.Circuits.Any(c=>c.Conductors!=null&&(c.Conductors.HasNeutral==true||c.Conductors.HasPEN==true));if((physicalN||neutral>1e-7)&&q.RequiresNeutral!=true)failures.Add("corrente/condutorN presente sem neutro exigido");if(q.RequiresNeutral==true){if(r.HasNeutral!=true)failures.Add("conjunto sem neutro");else{Need(r.NeutralRatedA.HasValue,"Capacidade do neutro não consta do catálogo.");if(neutral>result.CorrectedNeutralA)failures.Add("neutro acima da capacidade corrigida");}}
if(q.RequiredRmsUpperKA>r.IcwKA)failures.Add("RMS prospectivo acima deIcw");if(q.RequiredSeconds>r.IcwSeconds)failures.Add("tempo total superior ao domínioIcw");if(q.RequiredPeakKA>r.IpkKA)failures.Add("pico prospectivo acima deIpk");if(p.FaultExtremes!=null){var extremes=FaultExtremes.Run(p);Need(extremes.Accepted,"Perfil de extremos existente está incompleto.");var ids=new HashSet<string>(b.Circuits.Select(c=>c.Id));var points=extremes.Points.Where(x=>ids.Contains(x.CircuitId)&&x.Location=="Origem"&&x.Scenario.StartsWith("Máximo",StringComparison.Ordinal)).ToList();Need(points.Count>0,"Extremos não cobrem barramento deste quadro.");double initial=points.Max(x=>x.CurrentA)/1000;if(q.RequiredRmsUpperKA<initial)failures.Add("envelope declarado inferior ao maior curto inicial doF23");}
result.Failed=failures.Count>0;result.Accepted=!result.Failed;result.Status=result.Failed?"Não atende ao caso declarado":"Atende comparações locais do conjunto";result.Detail=(result.Failed?String.Join("; ",failures)+". ":"")+"Quadro "+b.Id+"; conjunto "+r.Reference+" / "+r.Configuration+"; "+r.Source+" / "+r.DataVersion+" / "+r.Conditions+". IRMSL1/L2/L3="+String.Join(" / ",currents.Select(x=>x.ToString("G10",CultureInfo.InvariantCulture)))+" A; IN="+neutral+" A; capacidade corrigida="+result.CorrectedRatedA+" A. Maior fase, não média. Fator="+q.CapacityFactor+"; "+q.CorrectionReference+"; "+q.OperatingConditions+". Correntes: "+q.CurrentReference+"; senoidal: "+q.SinusoidalReference+". Montagem: "+q.MountingReference+". Curto: envelope="+q.RequiredRmsUpperKA+" kA / "+q.RequiredSeconds+" s; pico="+q.RequiredPeakKA+" kA; catálogoIcw="+r.IcwKA+" kA / "+r.IcwSeconds+" s; Ipk="+r.IpkKA+" kA. "+q.FaultReference+"; "+q.FaultConditions+". Sem extrapolaçãoIcw/√t, limitação presumida por proteção, certificaçãoIEC61439, faltaN/PE ou queda do trecho busway. Conjunto selecionado ao nível do quadro; condutores dos circuitos mantêm estudos próprios.";return result;}catch(Input e){result.Status="Dados incompletos/incompatíveis";result.Detail=e.Message;result.PhaseRmsA=null;result.NeutralRmsA=result.CorrectedRatedA=result.CorrectedNeutralA=null;return result;}}
}
